(function (global) {
  "use strict";

  var files = "abcdefgh";
  var glyphs = { K:"♔", Q:"♕", R:"♖", B:"♗", N:"♘", P:"♙", k:"♚", q:"♛", r:"♜", b:"♝", n:"♞", p:"♟" };
  var startFen = "rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR";

  function parsePosition(position) {
    var fen = position === "start" || !position ? startFen : String(position).split(" ")[0];
    var rows = fen.split("/");
    var pieces = {};
    rows.forEach(function (row, rowIndex) {
      var fileIndex = 0;
      for (var i = 0; i < row.length; i += 1) {
        var token = row[i];
        if (/\d/.test(token)) fileIndex += Number(token);
        else {
          pieces[files[fileIndex] + String(8 - rowIndex)] = token;
          fileIndex += 1;
        }
      }
    });
    return pieces;
  }

  function create(container, options) {
    var position = options && options.position ? options.position : "start";
    var pieces = parsePosition(position);

    function render(arrivedSquare) {
      var markup = [];
      for (var rank = 8; rank >= 1; rank -= 1) {
        for (var file = 0; file < 8; file += 1) {
          var square = files[file] + rank;
          var piece = pieces[square];
          var color = (rank + file) % 2 === 0 ? "light" : "dark";
          var pieceClass = piece && piece === piece.toUpperCase() ? "white-piece" : "black-piece";
          var symbol = piece ? glyphs[piece] : "";
          markup.push('<div class="chess-square ' + color + (arrivedSquare === square ? " piece-arrived" : "") +
            '" role="gridcell" aria-label="' + square + '" data-square="' + square + '" tabindex="0">' +
            (symbol ? '<span class="' + pieceClass + '">' + symbol + '</span>' : "") + '</div>');
        }
      }
      container.innerHTML = markup.join("");
      container.setAttribute("role", "grid");
      container.setAttribute("aria-label", "Интерактивная шахматная доска");
    }

    render();
    return {
      position: function (nextPosition) {
        if (typeof nextPosition === "string" || nextPosition && typeof nextPosition === "object") {
          pieces = parsePosition(nextPosition);
          render();
        }
        return Object.assign({}, pieces);
      },
      movePiece: function (move, settings) {
        if (!move || !/^[a-h][1-8]$/.test(move.from) || !/^[a-h][1-8]$/.test(move.to)) return false;
        var piece = pieces[move.from];
        if (!piece) return false;
        pieces[move.to] = move.promotion || piece;
        delete pieces[move.from];
        render(settings && settings.animate ? move.to : null);
        return true;
      },
      destroy: function () { container.replaceChildren(); }
    };
  }

  global.MeridianChessboard = { create: create };
}(window));